+package main
+
+import (
+	"os"
+	"strings"
+	"testing"
+)
+
+func TestDashboardSessionsStoreOnlyHashedCredentials(t *testing.T) {
+	body, err := os.ReadFile("migrations/0009_dashboard_sessions.up.sql")
+	if err != nil {
+		t.Fatal(err)
+	}
+	for _, want := range []string{"provider IN ('github', 'gitlab')", "token_hash bytea PRIMARY KEY", "csrf_hash bytea NOT NULL", "REFERENCES dashboard_memberships(user_id, installation_id)"} {
+		if !strings.Contains(string(body), want) {
+			t.Fatalf("migration missing %q", want)
+		}
+	}
+	if strings.Contains(string(body), "access_token") || strings.Contains(string(body), "refresh_token") {
+		t.Fatal("migration persists OAuth bearer tokens")
+	}
+}

diff --git a/internal/hosted/dashboard/auth.go b/internal/hosted/dashboard/auth.go
new file mode 100644
index 0000000..b718f91
--- /dev/null
+++ b/internal/hosted/dashboard/auth.go
@@ -0,0 +1,67 @@
+// Package dashboard defines provider-neutral contracts for the hosted UI.
+package dashboard
+
+import (
+	"crypto/hmac"
+	"crypto/rand"
+	"encoding/base64"
+	"errors"
+	"strings"
+	"time"
+)
+
+type Provider string
+
+const (
+	ProviderGitHub Provider = "github"
+	ProviderGitLab Provider = "gitlab"
+)
+
+type Session struct {
+	ID             string
+	UserID         string
+	Provider       Provider
+	OrganizationID string
+	CSRFToken      string
+	ExpiresAt      time.Time
+}
+
+type Membership struct {
+	OrganizationID string
+	Active         bool
+}
+
+func NewSession(id, userID string, provider Provider, organizationID string, expiresAt time.Time) (Session, error) {
+	if strings.TrimSpace(id) == "" || strings.TrimSpace(userID) == "" || !validProvider(provider) || strings.TrimSpace(organizationID) == "" || !expiresAt.After(time.Now()) {
+		return Session{}, errors.New("valid session identity, provider, organization, and expiry are required")
+	}
+	token := make([]byte, 32)
+	if _, err := rand.Read(token); err != nil {
+		return Session{}, err
+	}
+	return Session{ID: id, UserID: userID, Provider: provider, OrganizationID: organizationID, CSRFToken: base64.RawURLEncoding.EncodeToString(token), ExpiresAt: expiresAt.UTC()}, nil
+}
+
+func (s Session) ValidateCSRF(token string, now time.Time) error {
+	if s.ID == "" || !now.Before(s.ExpiresAt) || token == "" || !hmac.Equal([]byte(s.CSRFToken), []byte(token)) {
+		return errors.New("invalid or expired session request")
+	}
+	return nil
+}
+
+func (s Session) SwitchOrganization(organizationID string, memberships []Membership, now time.Time) (Session, error) {
+	if s.ID == "" || !now.Before(s.ExpiresAt) || organizationID == "" {
+		return Session{}, errors.New("active session and organization are required")
+	}
+	for _, membership := range memberships {
+		if membership.Active && hmac.Equal([]byte(membership.OrganizationID), []byte(organizationID)) {
+			s.OrganizationID = organizationID
+			return s, nil
+		}
+	}
+	return Session{}, errors.New("user is not an active organization member")
+}
+
+func validProvider(provider Provider) bool {
+	return provider == ProviderGitHub || provider == ProviderGitLab
+}

diff --git a/internal/hosted/dashboard/auth_test.go b/internal/hosted/dashboard/auth_test.go
new file mode 100644
index 0000000..2cc1dc7
--- /dev/null
+++ b/internal/hosted/dashboard/auth_test.go
@@ -0,0 +1,42 @@
+package dashboard
+
+import (
+	"testing"
+	"time"
+)
+
+func TestSessionCSRFAndOrganizationSwitch(t *testing.T) {
+	now := time.Date(2026, 10, 26, 10, 0, 0, 0, time.UTC)
+	// NewSession checks the real clock, so use a future expiry and validate at a
+	// fixed earlier instant to keep request-boundary assertions deterministic.
+	session, err := NewSession("session-1", "user-1", ProviderGitHub, "org-1", time.Now().Add(time.Hour))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := session.ValidateCSRF(session.CSRFToken, now); err != nil {
+		t.Fatal(err)
+	}
+	if err := session.ValidateCSRF("wrong", now); err == nil {
+		t.Fatal("accepted wrong CSRF token")
+	}
+	switched, err := session.SwitchOrganization("org-2", []Membership{{OrganizationID: "org-2", Active: true}}, now)
+	if err != nil || switched.OrganizationID != "org-2" {
+		t.Fatalf("session=%#v err=%v", switched, err)
+	}
+	if _, err := session.SwitchOrganization("org-3", []Membership{{OrganizationID: "org-3", Active: false}}, now); err == nil {
+		t.Fatal("switched to inactive organization")
+	}
+}
+
+func TestSessionRejectsUnknownProviderAndExpiredRequests(t *testing.T) {
+	if _, err := NewSession("s", "u", Provider("other"), "org", time.Now().Add(time.Hour)); err == nil {
+		t.Fatal("accepted unsupported OAuth provider")
+	}
+	session, err := NewSession("s", "u", ProviderGitLab, "org", time.Now().Add(time.Hour))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := session.ValidateCSRF(session.CSRFToken, session.ExpiresAt); err == nil {
+		t.Fatal("accepted expired session")
+	}
+}

